  win(g, [90, 91], [8, 9], [9], "x");
  win(g, [86, 87], [3, 4], [8], "x");
  win(g, [86, 87], [8, 9], [8], "x");
  porchWrap(g, { x0: 85, x1: 94, z0: 7, z1: 15, y: 1, gap: [89, 90] });
  win(g, [92], [3, 4, 8, 9], [11, 13], "z");
  win(g, [85], [3, 4, 8, 9], [12], "z");
  win(g, [88], [3, 4], [15], "x");
  doorDouble(g, 86, 7, 15, "south", "dark_oak", "x");
  balcony(g, 85, 6, 16);
  ramp(g, 89, 2, 6, "mangrove", null);
}

